# ------------------------------------------------------------------------------
# 6. HÀM TIỆN ÍCH CHUẨN HÓA & ĐỊNH DẠNG
# ------------------------------------------------------------------------------
def normalize_text(text: str) -> str:
    """Chuẩn hóa chuỗi tìm kiếm: bỏ dấu tiếng Việt, chữ thường, bỏ ký tự thừa."""
    if not text:
        return ""
    text = unicodedata.normalize("NFD", text)
    text = "".join(c for c in text if unicodedata.category(c) != "Mn")
    text = text.replace("đ", "d").replace("Đ", "d")
    return re.sub(r"\s+", " ", text).strip().lower()


def format_big_number(val: Union[int, float]) -> str:
    """Định dạng số lớn theo phong cách người chơi NRO (Tỷ, Triệu, k)."""
    try:
        val = int(val)
    except (ValueError, TypeError):
        return str(val)
    sign = "-" if val < 0 else ""
    abs_val = abs(val)
    if abs_val >= 1_000_000_000:
        return f"{sign}{abs_val / 1_000_000_000:.1f} Tỷ"
    if abs_val >= 1_000_000:
        return f"{sign}{abs_val / 1_000_000:.1f} Tr"
    if abs_val >= 1_000:
        return f"{sign}{abs_val / 1_000:.1f}k"
    return f"{sign}{abs_val}"


def format_compact_number(val: Union[int, float]) -> str:
    """Định dạng số cực ngắn gọn theo phong cách k, tr, tỷ (ví dụ: 13.5 tỷ, 13.9tr, 32.1k, 637)."""
    try:
        val = int(val)
    except (ValueError, TypeError):
        return str(val)
    sign = "-" if val < 0 else ""
    abs_val = abs(val)
    if abs_val >= 1_000_000_000:
        s = f"{abs_val / 1_000_000_000:.1f}"
        if s.endswith(".0"):
            s = s[:-2]
        return f"{sign}{s} tỷ"
    if abs_val >= 1_000_000:
        s = f"{abs_val / 1_000_000:.1f}"
        if s.endswith(".0"):
            s = s[:-2]
        return f"{sign}{s}tr"
    if abs_val >= 1_000:
        s = f"{abs_val / 1_000:.1f}"
        if s.endswith(".0"):
            s = s[:-2]
        return f"{sign}{s}k"
    return f"{sign}{abs_val}"


# ------------------------------------------------------------------------------
# 7. CÁC HÀM TRA CỨU NHANH (LOOKUP HELPERS)
# ------------------------------------------------------------------------------
def get_item_name(template_id: int, fallback_info: str = "") -> str:
    """Lấy tên chuẩn của vật phẩm từ ID (1,468 items)."""
    if template_id in ITEM_NAMES:
        return ITEM_NAMES[template_id]
    if fallback_info and fallback_info.strip():
        return fallback_info.strip()
    return f"Vật phẩm #{template_id}"

# Alias tương thích ngược cho telegram_bot
get_item_display_name = get_item_name


def get_item_info(template_id: int) -> Optional[Dict[str, Any]]:
    """Lấy thông tin chi tiết đầy đủ của vật phẩm (id, name, type, gender, desc, level, req)."""
    return ITEM_TEMPLATES.get(template_id)


def get_item_type_name(type_id: int) -> str:
    """Lấy tên phân loại vật phẩm (Áo, Quần, Găng tay, Ngọc Rồng, Capsule...)."""
    return ITEM_TYPE_NAMES.get(type_id, f"Loại {type_id}")


def get_gender_name(gender_id: int) -> str:
    """Lấy tên hành tinh theo gender_id (0: Trái Đất, 1: Namếc, 2: Xayda, 3: Tất cả hành tinh)."""
    return GENDER_NAMES.get(gender_id, "Tất cả")


def format_item_details(template_id: int) -> str:
    """Tạo chuỗi mô tả ngắn gọn thông tin vật phẩm từ game_data."""
    info = get_item_info(template_id)
    if not info:
        return ""
    parts = []
    type_name = get_item_type_name(info.get("type", -1))
    gender_name = get_gender_name(info.get("gender", 3))
    parts.append(f"Loại: {type_name}")
    if gender_name != "Tất cả hành tinh":
        parts.append(f"Hành tinh: {gender_name}")
    level = info.get("level", 0)
    if level > 0:
        parts.append(f"Cấp: {level}")
    req = info.get("req", 0)
    if req > 0:
        parts.append(f"Yêu cầu SM: {format_big_number(req)}")
    desc = info.get("desc", "").strip()
    if desc and desc != "...":
        parts.append(f"Mô tả: {desc}")
    return " | ".join(parts)


