# ------------------------------------------------------------------------------
# 8. CÁC HÀM TÌM KIẾM THEO TỪ KHÓA (SEARCH HELPERS)
# ------------------------------------------------------------------------------
def search_items(query: str, limit: int = 15) -> List[Dict[str, Any]]:
    """Tìm kiếm vật phẩm theo ID hoặc từ khóa tên (hỗ trợ không dấu)."""
    q = query.strip()
    if not q:
        return []
    if q.isdigit():
        tid = int(q)
        if tid in ITEM_TEMPLATES:
            return [ITEM_TEMPLATES[tid]]
        return []

    q_norm = normalize_text(q)
    results = []
    for it in ITEM_TEMPLATES.values():
        name_norm = normalize_text(it["name"])
        if q_norm in name_norm:
            results.append(it)
            if len(results) >= limit:
                break
    return results


def search_maps(query: str, limit: int = 15) -> List[Tuple[int, str]]:
    """Tìm kiếm bản đồ theo ID hoặc từ khóa tên (hỗ trợ không dấu)."""
    q = query.strip()
    if not q:
        return []
    if q.isdigit():
        mid = int(q)
        if mid in MAP_NAMES:
            return [(mid, MAP_NAMES[mid])]
        return []

    q_norm = normalize_text(q)
    results = []
    for mid, name in MAP_NAMES.items():
        name_norm = normalize_text(name)
        if q_norm in name_norm:
            results.append((mid, name))
            if len(results) >= limit:
                break
    return results


def search_mobs(query: str, limit: int = 15) -> List[Dict[str, Any]]:
    """Tìm kiếm quái vật theo ID hoặc từ khóa tên."""
